            <h4>2.静态资源服务端(<a class="content-link" href="https://github.com/tagaryen/tagaryen.github.io/releases/download/resources-download-2/static-server">下载</a>)</h4>
            <p>用于快速部署原型或静态网站。</p>
            <ImageShow/>
          </li>
        </ul>
      </div>
    </div>
    <div v-if="toolActive!==''" class="archer-tool">
      <div v-if="toolActive!==''" class="tool-close"><div class="tool-close-btn" @click="toolClose">&times;</div></div>
      <Json v-if="toolActive==='json'"/>
      <MdEditor v-if="toolActive==='mdeditor'"/>
      <ImageConvert v-if="toolActive==='imageconvert'"/>
    </div>
