</template>

<script>
import Json from "./Json.vue"
import MdEditor from './MdEditor.vue'
import ImageConvert from './ImageConvert.vue'
import ImageView from './ImageView.vue'
import ImageShow from './ImageShow.vue'
import time from "@/util/time"

export default {
  name: "Home",
  components: {
    Json,
    MdEditor,
    ImageConvert,
    ImageView,
    ImageShow
  },
  data() {
    return {
      time:{
        currentTime: new Date(),
        isDarkTheme: true
      },
      toolActive: '',
      searchMessageContent: '',
      staticServerImgUrl: require('@/assets/image/static.png')
    };
  },
  mounted() {
    let self = this;
    time.schedule(() => {
      self.time.currentTime = new Date()
    }, 1000);
  },
  methods: {
    toggleTheme() {
      this.time.isDarkTheme = !this.time.isDarkTheme;
      document.body.classList.toggle('dark-theme', this.time.isDarkTheme);
    },
    formatDate(date) {
      let year = date.getFullYear();
      let month = date.getMonth() + 1;
      let day = date.getDate();
      let dayOfWeek = ['日', '一', '二', '三', '四', '五', '六'][date.getDay()];
      
      return {
        year: `${year}年`,
        month: `${month}月`,
        day: day < 10 ? `0${day}` : `${day}`,
        dayOfWeek: `星期${dayOfWeek}`
      };
    },
        
    formatTime(date) {
      let hours = date.getHours();
      let minutes = date.getMinutes();
      let seconds = date.getSeconds();
      
      return {
        hours: hours < 10 ? `0${hours}` : `${hours}`,
        minutes: minutes < 10 ? `0${minutes}` : `${minutes}`,
        seconds: seconds < 10 ? `0${seconds}` : `${seconds}`
      };
    },
    toolClose() {
      this.toolActive = '';
    },
    jsonSection() {
      this.toolActive = 'json';
    },
    mdSection() {
      this.toolActive = 'mdeditor';
    },
    icSection() {
      this.toolActive = 'imageconvert';
    },
    // apiSection() {
    //   this.toolActive = 'httpapi';
    // },
    openUrl(url) {
      window.open(url);
    },
    searchMessage() {
      if(this.searchMessageContent.trim() === '') {
        return
      }
      let content = this.searchMessageContent;
      this.searchMessageContent = ''
      window.open("https://cn.bing.com/search?q="+encodeURI(content))
    }
  },
};
</script>

