<template>
  <div class="Json">
    <div class="json-head-bar">
      <div class="json-head-btn" @click="jsonFormat">格式化</div>
      <div class="json-head-title">JSON美化工具</div>
      <div class="json-head-btn" @click="jsonStringify">压缩</div>
    </div>
    <div class="json-text-area">
      <textarea 
      v-model="jsonVal" placeholder="在此输入json字符串..."></textarea>
    </div>
  </div>
</template>

<script>
  import {beautifyJsonString, jsonSimplify} from '@/util/json'
  export default {
    components: {},
    data(){
      return {
        ok: false,
        jsonVal: "",
        jsonResults: [],
        btnHover: false
      }
    },
    mounted(){
    },
    methods: {
      jsonFormat() {
        if(this.jsonVal !== '') {
          this.jsonResults = beautifyJsonString(this.jsonVal);
          this.jsonVal = this.jsonResults.join("\n");
        }
      },
      jsonStringify() {
        this.jsonVal = jsonSimplify(this.jsonResults);
        this.jsonResults = [];
      }
    }
  }
</script>

<style lang="scss" scoped>
  .Json{
    background-color: #ffffff;
    background-size: 100% 100%;
    display: block;
    padding: 10px;

    
    .json-head-bar{
      display: flex;
      justify-content: space-between;
      text-align: center;
      height: 36px;
      width: 100%;

      .json-head-btn {
        background-color: rgb(117, 149, 253);
        color: rgb(255, 255, 255);
        height: 30px;
        width: 64px;
        border-radius: 4px;
        text-align: center;
        line-height: 30px;
      }
      .json-head-btn:hover {
        background-color: rgb(161, 182, 252);
        cursor: pointer;
      }
      .json-head-title {
        height: 30px;
        font-weight: 800;
        font-size: 18px;
        text-align: center;
      }
    }

    .json-text-area {
      height: calc(100% - 40px);
      width: 100%;

      textarea {
        height: calc(100% - 34px);
        width: calc(100% - 34px);
        border: 2px solid #e0e0e0;
        border-radius: 12px;
        padding: 15px;
        font-size: 16px;
        font-family:Arial, Helvetica, sans-serif;
        resize: none;
        transition: border-color 0.3s;
      }
      
      textarea:focus {
        outline: none;
        border-color: #8f94fb;
      }
    }

  }

</style>
  