<template>
    <div class="image-show" @click="openImg">
        <img :src=staticServerImgUrl alt="静态资源服务展示" style="height: 160px; width: 300px;"/>
    </div>
</template>
<script>

export default  {
    name: "ImageShow",
    data() {
        let staticServerImgUrl = require('@/assets/image/static.png');
        let {imgShow, imgMask} = this.createEl(staticServerImgUrl);
        return {
            showImg: false,
            staticServerImgUrl: staticServerImgUrl,
            imgMask: imgMask,
            imgShow: imgShow,
        }
    },
    methods: {
        createEl(url) {
            let imgShow = document.createElement('div');
            imgShow.classList.add('image-show-container');
            imgShow.id = "image-show-container"
            let button = document.createElement('button');
            button.classList.add('image-show-close-btn');
            button.onclick = this.closeImg;
            button.innerHTML = '&times;';
            let img = document.createElement('img');
            img.classList.add('image-show-model');
            img.src = url;
            img.alt = '静态资源服务展示';

            imgShow.appendChild(button);
            imgShow.appendChild(img);


            
            let imgMask = document.createElement('div');
            imgMask.id = "image-view-mask"
            imgMask.style.height = window.innerHeight + "px",
            imgMask.style.width = window.innerWidth + "px";
            imgMask.style.backgroundColor = "black"
            imgMask.style.opacity = 0.1;
            imgMask.style.position = 'fixed';
            imgMask.style.top = 0;
            imgMask.style.left = 0;
            imgMask.onclick = this.closeImg;

            return {imgShow, imgMask};
        },
        openImg() {
            if(this.showImg) {
                this.imgError = false;
            }
            this.showImg = true;
            this.imgMask.style.height = window.innerHeight + "px",
            this.imgMask.style.width = window.innerWidth + "px";
            this.imgShow.style.height = "500px",
            this.imgShow.style.width = "800px";
            let imgMask = document.getElementById('image-view-mask');
            if(!imgMask) {
                document.body.appendChild(this.imgMask);
            }
            let imgShow = document.getElementById('image-show-container');
            if(!imgShow) {
                document.body.appendChild(this.imgShow);
            }
        },
        closeImg() {
            if (!this.showImg) return;
            this.showImg = false;
            this.imgError = false;
            document.body.removeChild(this.imgMask);
            document.body.removeChild(this.imgShow);
        }
    }
}
</script>
<style>
    .image-show {
        border-radius: 8px;
        overflow: hidden;
        box-shadow: 0 25px 45px -12px rgba(0, 0, 0, 0.35), 0 8px 18px rgba(0, 0, 0, 0.1);
        height: 160px; 
        width: 300px;
        :hover {
            cursor: pointer;
        }
    }
    .image-show-container {
        position: fixed;
        width: 800px;
        height: 500px;
        top: 40%;
        left: 50%;
        transform: translate(-50%, -35%);
        background: transparent;
        border-radius: 8px;
        display: flex;
        flex-direction: column;
        align-items: center;
        justify-content: center;
        animation: zoomIn 0.2s ease-out;
        z-index: 1000;
    }
    /* 大图样式 */
    .image-show-model {
        width: 100%;
        height: 100%;
        object-fit: contain;
        border-radius: 8px;
        box-shadow: 0 10px 25px rgba(0, 0, 0, 0.3);
        background: #fff;
        display: block;
    }

    /* 关闭按钮 */
    .image-show-close-btn {
        position: absolute;
        top: 0;
        right: 0;
        background: rgba(0, 0, 0, 0.6);
        color: white;
        border: none;
        font-size: 28px;
        font-weight: bold;
        width: 40px;
        height: 40px;
        line-height: 1;
        border-radius: 50%;
        cursor: pointer;
        transition: background 0.2s;
        display: flex;
        align-items: center;
        justify-content: center;
        z-index: 10;
    }

    .image-show-close-btn:hover {
        background: rgba(0, 0, 0, 0.9);
        transform: scale(1.05);
    }
</style>
